INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5042, 174772, 'tt2051879', NULL, 'Europa Report', 'Europa Report', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/tbsfaBjiAW5vfrV06R8KCOzVOYy.jpg', 'https://image.tmdb.org/t/p/original/nnGluGp4Bowcy7STdDAEScQcwzV.jpg', 'A crew travels to Europa, Jupiter’s icy moon, to investigate signs of life in its subsurface ocean, but disaster cuts them off from Earth, leading to a tense and dangerous exploration.', NULL, NULL, 2.8779, 6.298, 0, 3.08333333333333348e+00, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5043, 369972, 'tt1213641', NULL, 'First Man', 'First Man', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/i91mfvFcPPlaegcbOyjGgiWfZzh.jpg', 'https://image.tmdb.org/t/p/original/jrudoaXcoLyHRPdolyOGemXgPEs.jpg', 'A look at the life of the astronaut, Neil Armstrong, and the legendary space mission that led him to become the first man to walk on the Moon on July 20, 1969.', NULL, NULL, 6.5682, 7.042, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5044, 199327, 'tt2856930', NULL, 'Gagarin: First in Space', 'Гагарин. Первый в космосе', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/nTk9rVyHIq89SgvEs91jzxq51ou.jpg', 'https://image.tmdb.org/t/p/original/hV2TytMYvduusLFnk1Y8N16n2ok.jpg', 'The film is dedicated to the first steps of mankind on the path of space exploration and direct the fate of the first cosmonaut Yuri Gagarin. The main motif - the fight for the right to be first: the competition in the first cosmonaut, competition in missile technology, the confrontation of superpowers - the USSR and the USA.  In the first group of astronauts were selected from three thousand fighter pilots across the country. In twenty of the legendary got the best of the best. Which of them will fly first, no one knew. In this way, had to contend not only with the pull of the earth ...', NULL, NULL, 1.2505, 6.278, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5045, 471498, 'tt6341832', NULL, 'Oxygen', 'Oxygène', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/u74DFoZGTcZ8cuHO8nvQkCqXEVP.jpg', 'https://image.tmdb.org/t/p/original/jedggylU3FyIN7XRAl9WY8mrT6H.jpg', 'A woman wakes in a cryogenic chamber with no recollection of how she got there, and must find a way out before running out of air.', NULL, NULL, 2.7399, 6.607, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5046, 13494, 'tt0800175', NULL, 'Red Sonja', 'Red Sonja', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/aE3yh4y0h96CZZpLo0UDFMWZAA9.jpg', 'https://image.tmdb.org/t/p/original/xSD0q1FiuZkvHuy7uscOLbmd1hR.jpg', 'A young girl rises from the ashes of tragedy to become the most feared warrior woman of all time: the She-Devil with a Sword.', NULL, NULL, 10.9171, 5.656, 0, 2.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5047, 37933, 'tt0495596', NULL, 'Tales from Earthsea', 'ゲド戦記', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/y0VnJt4eRPMjA1hpJ8f1EFoVaSf.jpg', 'https://image.tmdb.org/t/p/original/x5ufEAM7bS7DVXaovApamQh5BNE.jpg', 'Something bizarre has come over the land. The kingdom is deteriorating. People are beginning to act strange... What''s even more strange is that people are beginning to see dragons, which shouldn''t enter the world of humans. Due to all these bizarre events, Ged, a wandering wizard, is investigating the cause. During his journey, he meets Prince Arren, a young distraught teenage boy. While Arren may look like a shy young teen, he has a severe dark side, which grants him strength, hatred, ruthlessness and has no mercy, especially when it comes to protecting Teru. For the witch Kumo this is a perfect opportunity. She can use the boy''s "fears" against the very one who would help him, Ged.', NULL, NULL, 3.5879, 6.531, 0, 1.29, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5048, 42713, 'tt0100044', NULL, 'Record of Lodoss War', 'ロードス島戦記', 'tv', 1990, 'https://image.tmdb.org/t/p/w500/4DmzoxYfS4A1eFA35QIEJCvZE4D.jpg', 'https://image.tmdb.org/t/p/original/lOVKwI5TtcZMiB94Gkn9Tj1uu7k.jpg', 'Born in battle, baptized in fire, it''s kingdoms have been ravaged by war for thousands of years.  Now, an evil stirs, an ancient goddess of destruction awakened by an evil wizard.  A party of six is forged to defeat this threat, or die in the attempt.  Join Parn, the young fighter, as he leads his warriors into the heart of a land where dragons rule and evil holds sway over the earth.  Six swords are now drawn against this darkness.  The war for Lodoss has begun!', NULL, NULL, 7.2122, 7.507, 0, 2.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5049, 1154516, NULL, NULL, 'Quark the Dragon Slayer', 'Quark the Dragon Slayer', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/5SAmwUKWhW1PAaAQn0uNTOVxt0X.jpg', NULL, 'Collection of several Danish animated shorts stitched together to make a Feature. Animations aired in Denmark December 2, 1987: The feature includes the following titles in order; "Baby Quark", "Quark and the Long Winter", "Quark and the Vikings", "Quark and the Mosquitos", "Quark and the Highway Robber", "Dragonslayer Quark", "Quark and the Princess" + "Popeye the Sailor Meets Sindbad the Sailor" (1936 ‧ Fantasy/Musical ‧ 16 mins)', NULL, NULL, 0.5117, 0.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5050, 8779, 'tt0138919', NULL, 'The Vision of Escaflowne', '天空のエスカフローネ', 'tv', 1996, 'https://image.tmdb.org/t/p/w500/6uX0Q7Sn9JYWbHqQ5ZRJoJKcTmp.jpg', 'https://image.tmdb.org/t/p/original/ko65bRVvUAaOJ9Xw6vmXc6rHWxC.jpg', 'High school student Hitomi is transported from Earth to the magical world of Gaea, where she meets boy prince Van Fanel, and is caught up in his quest to unite the countries of Gaea against the ominous Zaibach empire. On the way, she discovers an hidden ability and strives to unravel layers of mystery surrounding Van, his past, and the giant machine known as Escaflowne.', NULL, NULL, 9.3831, 8.134, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5051, 9610, 'tt0087078', NULL, 'Conan the Destroyer', 'Conan the Destroyer', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/m5i7S46DT1ESy7URkh2l92awGRr.jpg', 'https://image.tmdb.org/t/p/original/kAhjS7czQu0gtMVwDqfSBR2KjTF.jpg', 'Conan is commissioned by the evil queen Taramis to safely escort a teen princess and her powerful bodyguard to a far away castle to retrieve the magic Horn of Dagoth. Unknown to Conan, the queen plans to sacrifice the princess when she returns and inherit her kingdom after the bodyguard kills Conan. The queen''s plans fail to take into consideration Conan''s strength and cunning and the abilities of his sidekicks: the eccentric wizard Akiro, the warrior woman Zula, and the inept Malak. Together the hero and his allies must defeat both mortal and supernatural foes in this voyage to sword-and-sorcery land.', NULL, NULL, 4.4633, 6.141, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5052, 6094, 'tt13031912', NULL, 'The Cave of the Golden Rose', 'Fantaghirò', 'tv', 1991, 'https://image.tmdb.org/t/p/w500/hwZBwRBuKge2E5WsmC8DyMb3MNE.jpg', 'https://image.tmdb.org/t/p/original/tRNUf0jQJOy6l4eGdRUFWgAWUQX.jpg', 'The king desires nothing more than a male heir. But his wife gives birth to a girl Fantaghirò. When she refuses to marry years later, she is sent in the forest where she learns how to ride and fight like a man. She appears disguised in a duel with Prince Romualdo, the son of her father''s adversary. Both fall in love, but their marriage brings no peace to the united kingdom. Evil forces are trying to seize power.', NULL, NULL, 6.5646, 7.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
