INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5108, 9441, 'tt0120686', NULL, 'Stepmom', 'Stepmom', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/wMPv2Yz6QDzv6YhSbaqM48Medl1.jpg', 'https://image.tmdb.org/t/p/original/iteE4cNHQm8PWmWDuKcCCnMLhS3.jpg', 'Jackie is a divorced mother of two. Isabel is the career minded girlfriend of Jackie’s ex-husband Luke, forced into the role of unwelcome stepmother to their children. But when Jackie discovers she is ill, both women realise they must put aside their differences to find a common ground and celebrate life to the fullest, while they have the chance.', NULL, NULL, 3.6486, 7.16, 0, 4.025, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
