INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5110, 376659, 'tt4651520', NULL, 'Bad Moms', 'Bad Moms', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/u9q10ljhkLj0tNCjlVqe3DCjoU4.jpg', 'https://image.tmdb.org/t/p/original/zci26eN6YKEg9gPLUp3wB5eqcEx.jpg', 'When three overworked and under-appreciated moms are pushed beyond their limits, they ditch their conventional responsibilities for a jolt of long overdue freedom, fun, and comedic self-indulgence.', NULL, NULL, 6.1164, 6.5, 0, 1.05, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5111, 431530, 'tt6359956', NULL, 'A Bad Moms Christmas', 'A Bad Moms Christmas', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/gPNHolu7AGnrB7r5kvJRRTfwMFR.jpg', 'https://image.tmdb.org/t/p/original/aIF2xRhE7iGxQd6ITGNrwYdGB9e.jpg', 'Amy, Kiki and Carla – three under-appreciated and over-burdened women – rebel against the challenges and expectations of the Super Bowl for mothers: Christmas. And if creating a more perfect holiday for their families wasn’t hard enough, they have to do all of that while hosting and entertaining their own mothers.', NULL, NULL, 4.323, 6.321, 0, 1.05, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5112, 9585, 'tt0102555', NULL, 'Not Without My Daughter', 'Not Without My Daughter', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/aEMncPIHISpaIJmYaIstS0TVnb7.jpg', 'https://image.tmdb.org/t/p/original/cUqqeHxAeJ6heHOJjCKczNc9lhb.jpg', 'An American woman, trapped in Islamic Iran by her brutish husband, must find a way to escape with her daughter as well.', NULL, NULL, 4.4171, 6.7, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5113, 22414, 'tt0100395', NULL, 'Postcards from the Edge', 'Postcards from the Edge', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/uF7bO5UcenRgag0jpbVvKsGyfBK.jpg', 'https://image.tmdb.org/t/p/original/uuOw885XJq3i2UYi2etF8ml1d7K.jpg', 'A substance-addicted actress tries to look on the bright side even as she''s forced to move back in with her mother to avoid unemployment.', NULL, NULL, 6.725, 6.6, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5114, 226486, 'tt2103254', NULL, 'Tammy', 'Tammy', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/efsVMziwE9BNTDX5fNmYVA5oAzJ.jpg', 'https://image.tmdb.org/t/p/original/bZ6rSw3rUGPvBkmIQMUG6tJJpkt.jpg', 'For burger-joint employee Tammy, a bad day keeps getting worse. She wrecks her car, loses her job, and finds that her husband has been unfaithful. It''s time to hit the road, but without money or transportation, Tammy''s options are limited. Her only choice is a road trip with her hard-drinking grandmother Pearl, who has a car, cash, and an itch to see Niagara Falls. It''s not the escape Tammy had in mind, but it may be what she needs.', NULL, NULL, 2.6321, 5.34, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5115, 12435, 'tt0489237', NULL, 'The Nanny Diaries', 'The Nanny Diaries', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/8hX6rcxnCidaqegPCyeFm9PODBn.jpg', 'https://image.tmdb.org/t/p/original/t5gmdPLPHSaEuGpSwxiH5wco0XS.jpg', 'A college graduate goes to work as a nanny for a rich New York family. Ensconced in their home, she has to juggle their dysfunction, a new romance, and the spoiled brat in her charge.', NULL, NULL, 3.2347, 6.384, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5116, 11215, 'tt0092605', NULL, 'Baby Boom', 'Baby Boom', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/4Jy5U4HITJWUDYJc1NGgJLIjbWz.jpg', 'https://image.tmdb.org/t/p/original/i3aD438nOLOASyf1KOZrDZxQXfX.jpg', 'J.C. Wiatt is a talented and ambitious New York City career woman who is married to her job and working towards partner at her firm. She has a live-in relationship with Steven, a successful investment broker who, along with J.C., agreed children aren''t part of the plan. J.C.''s life takes an unexpected turn when a distant relative dies and the will appoints her the caretaker of their baby girl, Elizabeth. The baby''s sudden arrival causes Steven to leave, breaking off their relationship. Juggling power lunches and powdered formula, she is soon forced off the fast track by a conniving colleague and a bigoted boss. But she won''t stay down for long. She''ll prove to the world that a woman can have it all and on her own terms too!', NULL, NULL, 2.8987, 6.397, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5117, 4587, 'tt0100140', NULL, 'Mermaids', 'Mermaids', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/1VufMcp0euY2LpmKiVv8xnbB9Om.jpg', 'https://image.tmdb.org/t/p/original/d4p6VPoN70CnTV74jbW5ltlDgsh.jpg', 'Fifteen-year-old Charlotte Flax is tired of her wacky mom moving their family to a different town any time she feels it is necessary. When they move to a small Massachusetts town and Mrs. Flax begins dating a shopkeeper, Charlotte and her 9-year-old sister, Kate, hope that they can finally settle down. But when Charlotte''s attraction to an older man gets in the way, the family must learn to accept each other for who they truly are.', NULL, NULL, 2.9752, 6.721, 0, 6.52, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5118, 77462, 'tt1987018', NULL, 'A Happy Event', 'Un heureux événement', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/qVUl6ktomxxkPu02LhFtiBsoFv7.jpg', 'https://image.tmdb.org/t/p/original/cOADBqxPLpYdmZZyFPuhjthdSoi.jpg', 'She drove me into a corner, then forced me to go beyond my limits. She made me confront the absolute: love, sacrifice, tenderness, abandonment. She dislocated me, transformed me. Why didn''t anyone warn me? Why doesn''t anyone ever talk about this?" Un heureux événement, or an intimate view of motherhood, sincere and with no taboos.', NULL, NULL, 1.3916, 6.013, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
