INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5179, 6877, 'tt0427229', NULL, 'Failure to Launch', 'Failure to Launch', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/omReuKQ8ItWYD5pOLmsKh3MF24w.jpg', 'https://image.tmdb.org/t/p/original/3fFVHmZcSIzG0ACExUz6pAhcSAR.jpg', 'At 35, Tripp has an interesting job, a hip car, a passion for sailing, an active dating life, and a great house - trouble is, he still lives with his parents, Al and Sue, who are not happy about it. Al and Sue are fascinated when friends whose adult son has recently moved away from home reveal they hired an expert to help. In desperation to push Tripp out of the nest once and for all, Al and Sue hatch a plan to hire Paula, an "interventionist," who has a formula in these cases.', NULL, NULL, 4.758, 5.844, 0, 2.015, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
