INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5217, 913814, 'tt13270424', NULL, 'Brian and Charles', 'Brian and Charles', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/pzP3N9qRo3S91QjfBFWNI0ph0AY.jpg', 'https://image.tmdb.org/t/p/original/sT0c22syDUXXz85Gg0E7dzZzCaA.jpg', 'An endearing outlier, Brian lives alone in a Welsh valley, inventing oddball contraptions that seldom work. After finding a discarded mannequin head, Brian gets an idea. Three days, a washing machine, and sundry spare parts later, he’s invented Charles, an artificially intelligent robot who learns English from a dictionary and proves a charming, cheeky companion. Before long, however, Charles also develops autonomy. Intrigued by the wider world — or whatever lies beyond the cottage where Brian has hidden him away — Charles craves adventure.', NULL, NULL, 1.592, 6.276, 0, 1.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
