INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5220, 10761, 'tt0866439', NULL, 'Made of Honor', 'Made of Honor', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/pDg8D0jNqmz7RbCBgblWvmPswHE.jpg', 'https://image.tmdb.org/t/p/original/qpzhGsHV6GJuEcZrOxNX8tw2j5L.jpg', 'Tom and Hannah have been platonic friends for 10 years. He''s a serial dater, while she wants marriage but hasn''t found Mr. Right. Just as Tom is starting to think that he is relationship material after all, Hannah gets engaged. When she asks Tom to be her ''maid'' of honor, he reluctantly agrees just so he can attempt to stop the wedding and woo her.', NULL, NULL, 3.9224, 6.471, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
