INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5223, 25195, 'tt1216492', NULL, 'Leap Year', 'Leap Year', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/i86hMi5iEF3WnYLCaGHdT5FPdYg.jpg', 'https://image.tmdb.org/t/p/original/6wlM6qQIiB7nb9mUYX95XjDLikX.jpg', 'When yet another anniversary passes without a marriage proposal from her boyfriend, Anna decides to take action. Aware of a Celtic tradition that allows women to pop the question on Feb. 29, she plans to follow her lover to Dublin and ask him to marry her. Fate has other plans, however, and Anna winds up on the other side of the Emerald Isle with handsome, but surly, Declan -- an Irishman who may just lead Anna down the road to true love.', NULL, NULL, 5.1815, 6.898, 0, 1.08, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
