INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5226, 40440, 'tt0075244', NULL, 'Led Zeppelin - The Song Remains the Same', 'Led Zeppelin - The Song Remains the Same', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/tQzNsYcg4rVXVGw45ue7nkdMOgs.jpg', 'https://image.tmdb.org/t/p/original/cQZrNORK4JHi0ljkHQgU9fO36cU.jpg', 'The best of Led Zeppelin''s legendary 1973 appearances at Madison Square Garden. Interspersed throughout the concert footage are behind-the-scenes moments with the band. The Song Remains the Same is Led Zeppelin at Madison Square Garden in NYC concert footage colorfully enhanced by sequences which are supposed to reflect each band member''s individual fantasies and hallucinations. Includes blistering live renditions of "Black Dog," "Dazed and Confused," "Stairway to Heaven," "Whole Lotta Love," "The Song Remains the Same," and "Rain Song" among others.', NULL, NULL, 1.1702, 7.816, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
