INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5232, 88909, 'tt0488046', NULL, 'Fatal Deviation', 'Fatal Deviation', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/9LhrDftREBcFUqoYm1BXuDFNCxv.jpg', 'https://image.tmdb.org/t/p/original/uGTKhMZMDDtVxC3DBCukRiuCDzZ.jpg', 'A young kenpo karate martial artist returns home after ten years in reform school on a quest to find out who murdered his father. He is befriended by an old monk and a local Irish beauty. His search takes him to the prestigious Bealtaine Martial Arts Tournament. Together with his past, the good guy is drawn into conflict with the local drug baron and his son, and the conflict makes the young man face his father''s death in a way he could never have imagined.', NULL, NULL, 1.5614, 5.5, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
