INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5234, 29918, 'tt0110305', NULL, 'Lassie', 'Lassie', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/mz8nOwwuOntjoBuIxNXePLzjZ32.jpg', 'https://image.tmdb.org/t/p/original/xX2vIe7mGE4wo1NSWFlxTQLV6cK.jpg', 'On their way to start a new life at a sheep farm in rural Virginia, the Turner family are halted by a wreck on the highway that has claimed the life of a truck driver. Spotting the trucker''s now-abandoned collie on the side of the road, they take pity on the dog and adopt her. As the city family copes with the change to rural life, including a feud with a neighboring farm family who resent the city interlopers, the ever-loyal Lassie helps them adjust to their new surroundings.', NULL, NULL, 2.3957, 6.132, 0, 1.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
