INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5277, 9919, 'tt0251127', NULL, 'How to Lose a Guy in 10 Days', 'How to Lose a Guy in 10 Days', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/2dlftyPz7mTYbrsPvTogyFmYd7d.jpg', 'https://image.tmdb.org/t/p/original/cdYj6HFpKp5NTmLiHHbNEGSmDT4.jpg', 'It''s the battle of wills, as Andie needs to prove she can dump a guy in 10 days, whereas Ben needs to prove he can win a girl in 10 days. Now, the clock is ticking—and the wildly entertaining comedy smash is off and running in this irresistible tale of sex, lies and outrageous romantic fireworks!', NULL, NULL, 9.0314, 6.869, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
