INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5280, 566228, 'tt8488126', NULL, 'The Inventor: Out for Blood in Silicon Valley', 'The Inventor: Out for Blood in Silicon Valley', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/u21ImPnHHX2SFgkdHIjwlpEwRux.jpg', 'https://image.tmdb.org/t/p/original/911kCT2YwGBhFz1CNDfb0La8ybG.jpg', 'With a magical new invention that promised to revolutionize blood testing, Elizabeth Holmes became the world’s youngest self-made billionaire, heralded as the next Steve Jobs. Then, overnight, her 10-billion-dollar company dissolved. The rise and fall of Theranos is a window into the psychology of fraud.', NULL, NULL, 1.1456, 7.03, 0, 2.015, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5281, 650, 'tt0101507', NULL, 'Boyz n the Hood', 'Boyz n the Hood', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/v4ox4aSCNT5vyLXl4Q71JiWwCXW.jpg', 'https://image.tmdb.org/t/p/original/w9Buzxn7RjbttP2xm9leMfMdyCP.jpg', 'In the middle of the Los Angeles ghetto, drugs, robberies and shootings dominate everyday life. During these times, Furious tries to raise his son Tre to be a decent person. Tre''s friends, on the other hand, have little regard for the law and drag the entire neighborhood into a street war...', NULL, NULL, 6.0523, 7.631, 0, 2.025, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5282, 20649, 'tt0112688', NULL, 'Clockers', 'Clockers', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/c79uqLJleho2a7OQayfrW5Ypphf.jpg', 'https://image.tmdb.org/t/p/original/xhYs4yaBnDNM3utncVzLmFVpAmK.jpg', 'Strike is a young city drug pusher under the tutelage of drug lord Rodney Little. When a night manager at a fast-food restaurant is found with four bullets in his body, Strike’s older brother turns himself in as the killer. Detective Rocco Klein doesn’t buy the story, however, setting out to find the truth, and it seems that all the fingers point toward Strike & Rodney.', NULL, NULL, 2.0689, 6.695, 0, 1.04, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5283, 16136, 'tt0104573', NULL, 'Juice', 'Juice', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/hfXFPMhNjLnCugBHMN0nrtKW7Ra.jpg', 'https://image.tmdb.org/t/p/original/54xcERdFHlRny2FJ9NC4koForkR.jpg', 'Four Harlem friends -- Bishop, Q, Steel and Raheem -- dabble in petty crime, but they decide to go big by knocking off a convenience store. Bishop, the magnetic leader of the group, has the gun. But Q has different aspirations. He wants to be a DJ and happens to have a gig the night of the robbery. Unfortunately for him, Bishop isn''t willing to take no for answer in a game where everything''s for keeps.', NULL, NULL, 2.7222, 7.221, 0, 1.04, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5284, 9516, 'tt0107554', NULL, 'Menace II Society', 'Menace II Society', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/nS7yqmSVeNoH22VXj69JoFCxW1h.jpg', 'https://image.tmdb.org/t/p/original/s5PP0ryxAo12jzvPntSEybahpCw.jpg', 'A young street hustler attempts to escape the rigors and temptations of the ghetto in a quest for a better life.', NULL, NULL, 3.6884, 7.5, 0, 1.04, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5285, 942486, 'tt0171583', NULL, 'The Moravian Land', 'O moravské zemi', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/mUUeHl94lG0Q0lJefjLUqwiU9Gj.jpg', NULL, 'The reason for making this film is clear: it was to cover up Vojtěch Jasný''s famous chronicle "All the Good Natives", an account of the tragic consequences of forced collectivisation. The pro-regime director Antonín Kachlík also focuses on the socialisation of the Moravian village, accompanied by mistakes and coercion, but in his optimistic view he emphasises the hopeful prospects leading to a happy future. Although the united village lands were born in pain, they will serve for the benefit of all the working people... As with Jasný, Radek Brzobohatý embodies the stubborn peasant, who is only slowly acknowledging the benefits of communal farming. However, unlike the poetic exuberance and pithiness of Jasný''s chronicle, here we encounter a vicious posturing.', NULL, NULL, 0.1969, 7.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5286, 621954, 'tt8846176', NULL, 'Concrete Cowboy', 'Concrete Cowboy', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/qRW2poVt06WCVlIhrolWS5af4YV.jpg', 'https://image.tmdb.org/t/p/original/9XPFB98nYhQG05btI1NDJidUg2J.jpg', 'Sent to live with his estranged father for the summer, a rebellious teen finds kinship in a tight-knit Philadelphia community of Black cowboys.', NULL, NULL, 1.0667, 6.077, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
