INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5288, 1481697, NULL, NULL, 'Building 187', 'Immeuble 187', 'movie', NULL, NULL, NULL, 'In war-torn Lebanon, neighbors in Bsalim experience the conflict solely through their television screens, trapped in a hypnotic cycle of fear and detachment.', NULL, NULL, 0.1092, 0.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5289, 9909, 'tt0112792', NULL, 'Dangerous Minds', 'Dangerous Minds', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/yWHWC8fJRp2kLgiFrEa8o3krOH9.jpg', 'https://image.tmdb.org/t/p/original/yK5vziICSiW6uHLltNqkZ1TXhNx.jpg', 'Former Marine Louanne Johnson lands a gig teaching in a pilot program for bright but underachieving teens at a notorious inner-city high school. After having a terrible first day, she decides she must throw decorum to the wind. When Johnson returns to the classroom, she does so armed with a no-nonsense attitude informed by her military training and a fearless determination to better the lives of her students -- no matter what the cost.', NULL, NULL, 3.7646, 6.99, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
