INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5292, 2824, 'tt0105933', NULL, 'The Adventures of Pete & Pete', 'The Adventures of Pete & Pete', 'tv', 1993, 'https://image.tmdb.org/t/p/w500/hfDDYKx5v7esCSidKxrDLDGTu3m.jpg', 'https://image.tmdb.org/t/p/original/2McrDIPnOQvg1ZZlQ3vBMD0xIma.jpg', 'Pete and Pete are two redheaded brothers living in the somewhat surreal town of Wellsville. Pete, the older of the two, narrates the stories about their adventures in everyday life.', NULL, NULL, 6.7877, 7.696, 0, 1.14000000000000012e+00, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5293, 57789, 'tt0106763', NULL, 'Double, Double, Toil and Trouble', 'Double, Double, Toil and Trouble', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/3nMrq5z9b8pADKGop7aAFk0DUtP.jpg', 'https://image.tmdb.org/t/p/original/fv01ZeWs69JWEnjSaKCJCilzKDm.jpg', 'On Halloween night, two precocious little girls try to save their parents from their nasty old capitalist aunt''s greedy clutches. Magic abounds and they meet mysterious new friends along the way.', NULL, NULL, 1.4419, 6.375, 0, 1.06, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5294, 591273, 'tt6566576', NULL, 'Fear Street: 1994', 'Fear Street: 1994', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/9J9Wy39ZjrVmfk7yMkulpcI5sy0.jpg', 'https://image.tmdb.org/t/p/original/vu5Y8qFqlzcboDbbZIMTAgj0KLb.jpg', 'After a series of brutal slayings, a teen and her friends take on an evil force that''s plagued their notorious town for centuries.', NULL, NULL, 5.0245, 6.7, 0, 1.15, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5295, 46404, 'tt2788518', NULL, 'Spooksville', 'Spooksville', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/eaNU0csokA8M2M4TvJYx46kiNs4.jpg', 'https://image.tmdb.org/t/p/original/9pvhrZk3NmfKBL0HQieabKAgLbp.jpg', 'Searching for a new start after the mysterious disappearance of his mother, Adam Freeman and his dad move to the small town of Springville. Actually, the town is better known as "Spooksville" because, well, weird things seem to have been happening there for centuries. At first Adam doesn''t believe in the tales of supernatural occurrences but soon begins to learn firsthand why the nickname was attached to his adopted hometown. Along with new friends Sally and Watch, Adam intends to save the town from surreal forces and solve the mystery of the supposed age-old curse. "Spooksville" is based on the acclaimed book series by author Christopher Pike.', NULL, NULL, 3.6348, 7.4, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5296, 21481, 'tt0467421', NULL, 'Twitches', 'Twitches', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/8ctDK5B0uR2gre2PxQSSkJZFmh.jpg', 'https://image.tmdb.org/t/p/original/biWonOe1GrPEMqvXhr7FbLox6xt.jpg', 'Twins separated at birth, Camryn and Alex meet by chance for the first time on their 21st birthday and discover they''re witches with the power to save their homeland of Coventry from the evil that threatens it. But when Camryn leaves Alex to face the darkness alone, will Coventry be doomed? Or will the sisters multiply their magic by standing together?', NULL, NULL, 2.7845, 6.8, 0, 6.06000000000000049e+00, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5297, 55328, 'tt0279513', NULL, 'When Good Ghouls Go Bad', 'When Good Ghouls Go Bad', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/2SKXCsd4a44CO9ZQU6hNt1Kk18c.jpg', 'https://image.tmdb.org/t/p/original/gdijc43648nmCDisRKcJmV0YHMv.jpg', 'In October of 1981, Curtis Danko, the creepy kid from the small town of Walker Falls, was killed in a mysterious accident. He left behind a warning to the town: "If you ever have another Halloween again, I will return and destroy you all!" Curtis was buried in a locked crypt, along with a sculpture so evil, that unearthly fates were said to await anyone who looked at it. Now, 20 years later, the Walker men have returned to Walker Falls. They start a chain of events that unleashes an army of zombies on the town. Has Curtis Danko risen from the grave to exact his revenge? And will the people of Walker Falls make it through the night?', NULL, NULL, 1.0593, 5.7, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
