INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5299, 2706, 'tt0094540', NULL, 'Roseanne', 'Roseanne', 'tv', 1988, 'https://image.tmdb.org/t/p/w500/4UARHgxTm7xwhcEHiVDwF0Gv4j0.jpg', 'https://image.tmdb.org/t/p/original/hwCKVqEAoPQK91I3ewx64N1zLhS.jpg', 'A working-class family struggles to get by on a limited income in the fictional town of Lanford, Illinois.', NULL, NULL, 4.3329, 6.768, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5300, 2913, 'tt0103352', NULL, 'Are You Afraid of the Dark?', 'Are You Afraid of the Dark?', 'tv', 1992, 'https://image.tmdb.org/t/p/w500/2HA7bHYyWgQ0CeEq2mVepY30I7j.jpg', 'https://image.tmdb.org/t/p/original/nXmuzHiT3ODY9v50x8ipfSAFaNs.jpg', 'This spooky anthology series for kids recounts ghost stories told by the young members of the Midnight Society as they gather around a campfire. Each episode opens with members of the Midnight Society at their secret spot in the woods, where they prepare their fire and the night''s storyteller announces the title of the his or her offering. However, the cameras soon leave the storyteller and switch to the tale being told.', NULL, NULL, 17.5054, 8.185, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5301, 11675, 'tt0120694', NULL, 'Halloween H20: 20 Years Later', 'Halloween H20: 20 Years Later', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/lqLXUm3oK59sGJKRH2Zjj2m3iMg.jpg', 'https://image.tmdb.org/t/p/original/A1LU0zDxrEhtMYpqDHbXkBJT6aP.jpg', 'Two decades after surviving a massacre on October 31, 1978, former baby sitter Laurie Strode finds herself hunted by persistent knife-wielder Michael Myers. Laurie now lives in Northern California under an assumed name, where she works as the headmistress of a private school. But it''s not far enough to escape Myers, who soon discovers her whereabouts. As Halloween descends upon Laurie''s peaceful community, a feeling of dread weighs upon her -- with good reason.', NULL, NULL, 4.7325, 6.05, 0, 2.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
