INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5327, 32563, 'tt0042464', NULL, 'The Flame and the Arrow', 'The Flame and the Arrow', 'movie', 1950, 'https://image.tmdb.org/t/p/w500/30edZxvbt7W8p8y5OsMX9XSWSwK.jpg', 'https://image.tmdb.org/t/p/original/vfcYCzuddR1fkOgFnRuVVbypFPB.jpg', 'Dardo, a Robin Hood-like figure, and his loyal followers use a Roman ruin in Medieval Lombardy as their headquarters as they conduct an insurgency against their Hessian conquerors.', NULL, NULL, 1.1466, 6.348, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5328, 1047223, 'tt28313478', NULL, 'The Vourdalak', 'Le Vourdalak', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/sNyfKJUgabNcKSOw7C7hag4ANiU.jpg', 'https://image.tmdb.org/t/p/original/4DZ9rYfdLvoehzGZ7wSjMfp3Uy2.jpg', 'The Marquis d’Urfé finds refuge in the home of a strange family after becoming lost in a hostile forest while working as an emissary for the King of France.', NULL, NULL, 2.4179, 6.4, 0, 1.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5329, 6520, 'tt0113071', NULL, 'First Knight', 'First Knight', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/dJH5bwtu3UxbwRsSlhlhmMrV8ZH.jpg', 'https://image.tmdb.org/t/p/original/tsgEdYjwWVhdGHv01djx7KdXDJm.jpg', 'The timeless tale of King Arthur and the legend of Camelot are retold in this passionate period drama. Arthur is reluctant to hand the crown to Lancelot, and Guinevere is torn between her loyalty to her husband and her growing love for his rival. But Lancelot must balance his loyalty to the throne with the rewards of true love.', NULL, NULL, 4.3876, 6.103, 0, 2.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5330, 427796, 'tt5869634', NULL, 'RSC Live: Hamlet', 'RSC Live: Hamlet', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/cB7iIJHS4U2Uvhx41L44GML9Oab.jpg', 'https://image.tmdb.org/t/p/original/s0uYRHjBBMICYYt2WwQaoIAVkEG.jpg', 'Hamlet has the world at his feet. Young, wealthy and living a hedonistic life studying abroad. Then word reaches him that his father is dead. Returning home he finds his world is utterly changed, his certainties smashed and his home a foreign land. Struggling to understand his place in a new world order he faces a stark choice. Submit, or rage against the injustice of his new reality. Simon Godwin directs Paapa Essiedu as Hamlet in Shakespeare''s searing tragedy. As relevant today as when it was written, Hamlet confronts each of us with the mirror of our own mortality in an imperfect world.  Hamlet played in the Royal Shakespeare Theatre, Stratford-upon-Avon until throughout summer 2016.', NULL, NULL, 0.5304, 8.2, 0, 7.01500000000000056e+00, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5331, 118189, 'tt14022350', NULL, 'The Serpent Queen', 'The Serpent Queen', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/qrpIpzbwoAZJTegfKSTlmz15jbf.jpg', 'https://image.tmdb.org/t/p/original/o1n5b8AI7UWeJ8yxFzunf9in5OB.jpg', 'Considered an immigrant, common and plain, Catherine de Medici is married into the 16th century French court as an orphaned teenager expected to bring a fortune in dowry and produce many heirs, only to discover that her husband is in love with an older woman, her dowry is unpaid and she’s unable to concieve. Yet, only with her intelligence and determination, she manages to keep her marriage alive and masters the bloodsport that is the monarchy better than anyone else, ruling France for 50 years.', NULL, NULL, 9.1674, 7.34, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5332, 47090, 'tt0100369', NULL, 'The Pit and the Pendulum', 'The Pit and the Pendulum', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/xq4pLMaMlVmDEzaxTrDqDa4ET25.jpg', 'https://image.tmdb.org/t/p/original/5DQTIIi4E0sQg6bzKaMfNUwMReP.jpg', 'Set during the height of Spanish Inquisition. The beautiful and kind-hearted Maria is arrested as a witch when she inadvertently cries out in horror at the public whipping of a child. As Maria’s husband Antonio tries to save her, Torquemada, the Grand Inquisitor, determines to punish Maria with torture for the desire she inflames in him. Loosely based on Edgar Allen Poe''s classic short story.', NULL, NULL, 2.5543, 5.8, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
