INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5347, 865, 'tt0093894', NULL, 'The Running Man', 'The Running Man', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/GTAUOhO4BN0peJVvxGEQydJvUO.jpg', 'https://image.tmdb.org/t/p/original/ssQ7IcGmgUJdFLv8cHY3vC3OR4f.jpg', 'By 2017, the global economy has collapsed and U.S. society has become a totalitarian police state, censoring all cultural activity. The government pacifies the populace by broadcasting a number of game shows in which convicted criminals fight for their lives, including the gladiator-style The Running Man, hosted by the ruthless Damon Killian, where “runners” attempt to evade “stalkers” and certain death for a chance to be pardoned and set free.', NULL, NULL, 5.8393, 6.538, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
