INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5376, 12146, 'tt0338188', NULL, 'The Missing', 'The Missing', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/86s5nw5F1G8lJtEowO0LBB4hoBW.jpg', 'https://image.tmdb.org/t/p/original/o8bs4oCB3qCooYfpMhXY4evNVLi.jpg', 'When rancher and single mother of two Maggie Gilkeson sees her teenage daughter, Lily, kidnapped by Apache rebels, she reluctantly accepts the help of her estranged father, Samuel, in tracking down the kidnappers. Along the way, the two must learn to reconcile the past and work together if they are going to have any hope of getting Lily back before she is taken over the border and forced to become a prostitute.', NULL, NULL, 2.9839, 6.303, 0, 1.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5377, 20862, 'tt0120321', NULL, 'Smoke Signals', 'Smoke Signals', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/dZ6smtO2cEm3nxVhWscYfKS0mYX.jpg', 'https://image.tmdb.org/t/p/original/5MvH0D3aGYRM9KeQL3Xtl853UyB.jpg', 'Young Native American man Thomas is a nerd in his reservation, wearing oversize glasses and telling everyone stories no-one wants to hear. His parents died in a fire in 1976, and Thomas was saved by Arnold. Arnold soon left his family, and Victor hasn''t seen his father for 10 years. When Victor hears Arnold has died, Thomas offers him funding for the trip to get Arnold''s remains.', NULL, NULL, 1.2469, 6.8, 0, 1.05, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5378, 361743, 'tt1745960', NULL, 'Top Gun: Maverick', 'Top Gun: Maverick', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', 'https://image.tmdb.org/t/p/original/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.', NULL, NULL, 36.8371, 8.158, 0, 7.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5379, 317838, NULL, NULL, 'The Black American Experience: Famous Activists: Paul Robeson & Richard Wright', 'The Black American Experience: Famous Activists: Paul Robeson & Richard Wright', 'movie', NULL, NULL, NULL, 'Redefining race relations through public discourse made legends of the two men profiled here: multitalented performer, writer, athlete and civil rights activist Paul Robeson, and literary giant Richard Wright (Native Son). For Robeson, this propensity ultimately cost him his career, leading to his blacklisting during the McCarthy era. For Wright, it fueled a body of work that brought the experience of being black in America to the world at large.', NULL, NULL, 0.0461, 0.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5380, 14384, 'tt0066390', NULL, 'Soldier Blue', 'Soldier Blue', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/2fRfVQpdrjAhvxwytG0scOqdQOJ.jpg', 'https://image.tmdb.org/t/p/original/296DBEB1l02sTcyqzHqbJF5wL70.jpg', 'After a cavalry group is massacred by the Cheyenne, only two survivors remain: Honus, a naive private devoted to his duty, and Cresta, a young woman who had lived with the Cheyenne two years and whose sympathies lie more with them than with the US government. Together, they must try to reach the cavalry''s main base camp. As they travel onward, Honus is torn between his growing affection for Cresta.', NULL, NULL, 2.1339, 6.765, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5381, 515042, 'tt7775622', NULL, 'Free Solo', 'Free Solo', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/v4QfYZMACODlWul9doN9RxE99ag.jpg', 'https://image.tmdb.org/t/p/original/z2uuQasY4gQJ8VDAFki746JWeQJ.jpg', 'Follow Alex Honnold as he attempts to become the first person to ever free solo climb Yosemite''s 3,000 foot high El Capitan wall. With no ropes or safety gear, this would arguably be the greatest feat in rock climbing history.', NULL, NULL, 2.7153, 7.9, 0, 1.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
