INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5383, 1452083, NULL, NULL, 'The Finisher: Jasmin Paris and the Barkley Marathons', 'The Finisher: Jasmin Paris and the Barkley Marathons', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/7ZwJHs1sVOdyLnoY3Px6vxsdSoH.jpg', NULL, 'In 2024, Jasmin Paris made history by becoming the first woman to finish the Barkley Marathons, widely known as one of the hardest races in the world and a defining test in ultrarunning and trail running. With over 100 miles of brutal terrain, cryptic course markings, and a near-impossible success rate, the Barkley has long been considered the ultimate challenge in endurance sports. The Finisher" chronicles Jasmin’s extraordinary three-year journey (2022–2024) to achieve this groundbreaking feat.', NULL, NULL, 0.7978, 6.0, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
