INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5419, 552309, 'tt7945340', NULL, 'The Dancing Pumpkin', 'The Dancing Pumpkin', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/8t8qnSEm1InR5uVS5NJqI2N6HbD.jpg', NULL, 'One magical night, four children discover that the jack-o-lantern on their doorstep is alive and a brilliant tap dancer. The children befriend the charismatic pumpkin, and set out on a thrilling adventure to stop the evil ogre, Finkgrinder, from his mission to hurt people. Giant Royal Thunderbelly pumpkins, weighing over five hundred pounds, carry the children to the ogre''s castle. Along the way, they are menaced by witches and helped by two comical skeletons named Helgi and Finbogi. In a dramatic finale, the Dancing Pumpkin and his friends succeed in foiling Finkgrinder''s plans. Packed with adventure, thrills, and unforgettable characters, this award-winning production will entertain the entire family!', NULL, NULL, 0.2939, 5.0, 0, 7.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5420, 522328, 'tt6233612', NULL, 'Happily Never After', 'Happily Never After', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/4g5bFBRbxbtQ6kWy7hsuF22uJD9.jpg', 'https://image.tmdb.org/t/p/original/tgAvHx3EvxNb1pWmbidY7jJPf1m.jpg', 'Kate is part of a writing duo with her boyfriend, and thinks her author days are over when they split, until her publisher requests a sequel.', NULL, NULL, 0.7237, 5.9, 0, 8.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
