INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5423, 12244, 'tt0472033', NULL, '9', '9', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/3uqXGOH4BQ2CLJWkDJZ0PzbUzOn.jpg', 'https://image.tmdb.org/t/p/original/t4V34FTYzZl0ZMdAXAK0T7DE3ie.jpg', 'When 9 first comes to life, he finds himself in a post-apocalyptic world. All humans are gone, and it is only by chance that he discovers a small community of others like him taking refuge from fearsome machines that roam the earth intent on their extinction. Despite being the neophyte of the group, 9 convinces the others that hiding will do them no good.', NULL, NULL, 7.6165, 6.958, 0, 8.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
