INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5425, 479367, 'tt0216035', NULL, 'The Night of the Headless Horseman', 'The Night of the Headless Horseman', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/gBN6o1KGzWlPoQXtE4fkCMJQyus.jpg', 'https://image.tmdb.org/t/p/original/sZB41gTDARHhTfrenGbaX1n0fSZ.jpg', 'The teacher Ichabod Crane arrives at Sleepy Hollow town and immediately falls in love with Katrina Van Tassel. Ichabold is intelligent, but weak and coward, and he finds a competitor, the strong Brom Bones that has been wooing Katrina for a long time. Soon begins a competition between the two men for Katrina, but Ichabold''s greatest problem is the Headless Horseman that haunts him.', NULL, NULL, 0.6107, 5.375, 0, 8.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
