INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5427, NULL, NULL, 79276, 'Goosebumps: Escape from Horrorland', 'Goosebumps: Escape from Horrorland', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wjb.jpg', NULL, 'Goosebumps: Escape from Horrorland is the interactive sequel to R.L. Stine''s kids'' horror novel, One Day at Horrorland. You and Lizzy, her brother Luke, and his friend Clay are once again trapped in Horrorland, a sinister, scary "theme park." When Luke and Clay are captured, you and Lizzy must find them and escape from the park with your lives. However, you must go up against a mummy, a werewolf, Dracula, and many more monsters in order to escape.', 'https://www.igdb.com/games/goosebumps-escape-from-horrorland', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
