INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5468, 84175, 'tt2125435', NULL, 'Beasts of the Southern Wild', 'Beasts of the Southern Wild', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/nQJmWekGYlXhezGUb21xFfEfwhH.jpg', 'https://image.tmdb.org/t/p/original/7LWLPvyfLSb2oOlgWwAwUqA8uKo.jpg', 'Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink, in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', NULL, NULL, 2.2017, 6.841, 0, 11.03, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
