INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5493, 2900, 'tt0138304', NULL, 'The Astronaut''s Wife', 'The Astronaut''s Wife', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/54RGJ6INW9ERG8IaalmMKbbDgwH.jpg', 'https://image.tmdb.org/t/p/original/c77Aq23NdM8UAzlH5GuniJBuCPd.jpg', 'When astronaut Spencer Armacost returns to Earth after a mission that nearly cost him his life, he decides to take a desk job in order to see his beautiful wife, Jillian, more often. Gradually, Jillian notices that Spencer''s personality seems to have changed, but her concerns fade when she discovers that she''s pregnant. As Jillian grows closer to becoming a mother, her suspicions about Spencer return. Why does it seem as if he''s a different person?', NULL, NULL, 2.3706, 5.602, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5494, 1011082, 'tt2015349', NULL, 'The Greatest Hits', 'The Greatest Hits', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg', 'https://image.tmdb.org/t/p/original/yIHbfIKg6udGn2amj3EJYupSjnA.jpg', 'Harriet finds art imitating life when she discovers certain songs can transport her back in time – literally. While she relives the past through romantic memories of her former boyfriend, her time travelling collides with a burgeoning new love interest in the present. As she takes her journey through the hypnotic connection between music and memory, she wonders – even if she could change the past, should she?', NULL, NULL, 2.5013, 6.472, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5495, 10215, 'tt0120148', NULL, 'Sliding Doors', 'Sliding Doors', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/s8VOVTywXZIIHqdEjkCZziH0ebq.jpg', 'https://image.tmdb.org/t/p/original/1dApwEEMrk7QnUb1EpyYWrG6nRh.jpg', 'Helen, a London ad executive, is fired from her job and rushes out to catch a train, but, as she runs down, her life suddenly splits off. In one version she catches the train; in the second, she misses it. Her whole life changes in that one second, and the rest of the film depicts what happens in each scenario.', NULL, NULL, 2.572, 6.556, 0, 1.05, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
