INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5507, 22345, 'tt0118665', NULL, 'Baby Geniuses', 'Baby Geniuses', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/7zvPhjHkz5YEMUMPyvANCR96RJA.jpg', 'https://image.tmdb.org/t/p/original/ywSzDrauG6R52H2zg0HkrPRgvYE.jpg', 'BabyCo is the world''s leading manufacturer in baby products. However, what the public doesn''t know, is that Drs Kinder and Heep, two of its most brilliant scientists, are tirelessly working in complete secrecy to crack the indecipherable code to ''baby talk'': a highly sophisticated language, and the key to the secrets of the universe. Before long, problems arise when mischievous Sly, the smartest of the toddlers, escapes confinement, bent on uniting all babies to free those trapped in the laboratory. Now, Kinder and Heep must find Sly before it is too late.', NULL, NULL, 2.1551, 4.114, 0, 1.02, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
