INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5539, 336000, 'tt2378507', NULL, 'The Glass Castle', 'The Glass Castle', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/8NPP7mliHLlVMHce8SjApiRxgzm.jpg', 'https://image.tmdb.org/t/p/original/lBDOPBbmI0mKqBAakiLZ0BdgzET.jpg', 'A young girl is raised in a dysfunctional family constantly on the run from the FBI. Living in poverty, she comes of age guided by her drunkard, ingenious father who distracts her with magical stories to keep her mind off the family''s dire state, and her selfish, nonconformist mother who has no intention of raising a family, along with her younger brother and sister, and her other older sister. Together, they fend for each other as they mature in an unorthodox journey that is their family life.', NULL, NULL, 3.5149, 7.105, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
