INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5589, 4480, 'tt0091288', NULL, 'Jean de Florette', 'Jean de Florette', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/atjyDRdOnOi2S28X3mNtJ7CQmFj.jpg', 'https://image.tmdb.org/t/p/original/qNBxyt60hnzBRSHo1uRkRU34fYE.jpg', 'In a rural French village, an old man and his only remaining relative cast their covetous eyes on an adjoining vacant property. They need its spring water for growing their flowers, and are dismayed to hear that the man who has inherited it is moving in. They block up the spring and watch as their new neighbour tries to keep his crops watered from wells far afield through the hot summer. Though they see his desperate efforts are breaking his health and his wife and daughter''s hearts, they think only of getting the water.', NULL, NULL, 2.0892, 7.679, 0, 11.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
