INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5600, 2410, 'tt0077003', NULL, 'Diff''rent Strokes', 'Diff''rent Strokes', 'tv', 1978, 'https://image.tmdb.org/t/p/w500/y3JYCzXPWqqPf8GI5f1pIeMAi9h.jpg', 'https://image.tmdb.org/t/p/original/p5aNm1QdtsOiN1id7OedFmOCLR.jpg', 'The series stars Gary Coleman and Todd Bridges as Arnold and Willis Jackson, two African American boys from Harlem who are taken in by a rich white Park Avenue businessman named Phillip Drummond and his daughter Kimberly, for whom their deceased mother previously worked. During the first season and first half of the second season, Charlotte Rae also starred as the Drummonds'' housekeeper, Mrs. Garrett.', NULL, NULL, 1.9283, 7.1, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5601, 6471, 'tt0079367', NULL, 'The Jerk', 'The Jerk', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/mIjOWtUofyt9Jawge7FbvITjU3D.jpg', 'https://image.tmdb.org/t/p/original/llVPUs3j9RywSMstGRepSeS8vSL.jpg', 'After discovering he''s not really black like the rest of his family, likable dimwit Navin Johnson sets off on a hilarious misadventure that takes him from rags to riches and back again. The slaphappy jerk strikes it rich, but life in the fast lane isn''t all it''s cracked up to be and, in the end, all that really matters to Johnson is his true love.', NULL, NULL, 3.1497, 6.88, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5602, 62852, 'tt4270492', NULL, 'Billions', 'Billions', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/edwYPQdZE998d748AdwWLsfy0rl.jpg', 'https://image.tmdb.org/t/p/original/51Hw58fMwJQKYJ6XYJIRQBP9EPA.jpg', 'Shrewd, savvy U.S. Attorney Chuck Rhoades and the brilliant, ambitious hedge fund king Bobby "Axe" Axelrod are on an explosive collision course, with each using all of his considerable smarts, power and influence to outmaneuver the other. The stakes are in the billions in this timely, provocative series.', NULL, NULL, 49.9761, 7.752, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5603, 66551, 'tt5638056', NULL, 'The Mick', 'The Mick', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/jwYBohob30EeP1rJJMx9zcWSaGS.jpg', 'https://image.tmdb.org/t/p/original/5xCxoMktHFsrcF283IMTL4OGtuR.jpg', 'Mackenzie "Mickey" Murphy is a hard-living, foul-mouthed, cigarette-smoking woman who moves to affluent Greenwich, CT to raise the spoiled kids of her wealthy sister who fled the country to avoid a federal indictment. She quickly learns what the rest of us already know - other people''s children are awful.', NULL, NULL, 10.6254, 7.132, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5604, 259316, 'tt3183660', NULL, 'Fantastic Beasts and Where to Find Them', 'Fantastic Beasts and Where to Find Them', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/fLsaFKExQt05yqjoAvKsmOMYvJR.jpg', 'https://image.tmdb.org/t/p/original/8Qsr8pvDL3s1jNZQ4HK1d1Xlvnh.jpg', 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.', NULL, NULL, 19.2021, 7.309, 0, 2.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5605, 86423, 'tt3007572', NULL, 'Locke & Key', 'Locke & Key', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/zuxGfRKziGHPogipnEXXykdDmyT.jpg', 'https://image.tmdb.org/t/p/original/nYxqUQaYGUv3pgMfe9BQ2WtUMQu.jpg', 'After their dad''s murder, three siblings move with their mom to his ancestral estate, where they discover magical keys that unlock powers — and secrets.', NULL, NULL, 14.4023, 7.742, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5606, 69581, 'tt5721172', NULL, 'The Worst Witch', 'The Worst Witch', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/fLhJKgPKeBsQaSe0i7VOnRQl37r.jpg', 'https://image.tmdb.org/t/p/original/rboZ8THSUD68ux24f9wuf4ptBln.jpg', 'Mayhem and mishaps follow young witch Mildred Hubble wherever she goes. She just can''t help it! But with her friends'' help, Mildred always manages to avoid disaster just in time.', NULL, NULL, 14.2282, 7.386, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5607, 10949, 'tt0040662', NULL, 'Oliver Twist', 'Oliver Twist', 'movie', 1948, 'https://image.tmdb.org/t/p/w500/wkMdDqXI58MuW99wi9kotC8kCVM.jpg', 'https://image.tmdb.org/t/p/original/cySQNHMxuWvNiIp2hZPjTaJFLwa.jpg', 'When 9-year-old orphan Oliver Twist dares to ask his cruel taskmaster, Mr. Bumble, for a second serving of gruel, he''s hired out as an apprentice. Escaping that dismal fate, young Oliver falls in with the street urchin known as the Artful Dodger and his criminal mentor, Fagin. When kindly Mr. Brownlow takes Oliver in, Fagin''s evil henchman Bill Sikes plots to kidnap the boy.', NULL, NULL, 4.0457, 7.55, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5608, 11904, 'tt0090357', NULL, 'Young Sherlock Holmes', 'Young Sherlock Holmes', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/aOxVYvQoAfNSns4hW5Ah55GBzgq.jpg', 'https://image.tmdb.org/t/p/original/depMebS7tRuR8ebxghxdkIlnX3s.jpg', 'Sherlock Holmes and Dr. Watson meet as boys in an English Boarding school. Holmes is known for his deductive ability even as a youth, amazing his classmates with his abilities. When they discover a plot to murder a series of British business men by an Egyptian cult, they move to stop it.', NULL, NULL, 2.8886, 6.754, 0, 3.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5609, 175774, 'tt2418558', NULL, 'Ruby Red', 'Rubinrot', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/lCfUO2be7jlskyTXRnf1bQtdIes.jpg', 'https://image.tmdb.org/t/p/original/6NZMN7XRb0TDRloST3P8T9W2z0W.jpg', 'On her 16th birthday, Gwendolyn Shepherd finds out that instead of her cousin, she has inherited a rare gene that allows her to travel through time.', NULL, NULL, 1.9141, 6.937, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
