INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5613, 60304, 'tt1428538', NULL, 'Hansel & Gretel: Witch Hunters', 'Hansel & Gretel: Witch Hunters', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/j343Rpj3WeNvP0SV80zveve70io.jpg', 'https://image.tmdb.org/t/p/original/mJSe5dxKu8Sq0GfdjdWVqdGvzfV.jpg', 'After getting a taste for blood as children, Hansel and Gretel have become the ultimate vigilantes, hell-bent on retribution. Now, unbeknownst to them, Hansel and Gretel have become the hunted, and must face an evil far greater than witches... their past.', NULL, NULL, 8.0567, 6.108, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5614, 262543, 'tt1971325', NULL, 'Automata', 'Autómata', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/h7SEtIWOfLsuCWhQgflev7ppRPq.jpg', 'https://image.tmdb.org/t/p/original/kVChi7qHX9UMcpAh7J6fGBCCH2c.jpg', 'Jacq Vaucan, an insurance agent of ROC robotics corporation, routinely investigates the case of manipulating a robot. What he discovers will have profound consequences for the future of humanity.', NULL, NULL, 5.0289, 5.894, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5615, 45952, 'tt0426719', NULL, 'Hunter x Hunter', 'HUNTER×HUNTER', 'tv', 1999, 'https://image.tmdb.org/t/p/w500/eobAuhCJA8oRp814V67WhezVXtQ.jpg', 'https://image.tmdb.org/t/p/original/575sxZXNNulSlIz7DvtWH5r4lkC.jpg', 'Gon Freecss discovers that the father he had always been told was dead was actually alive the whole time. Ging is a famous Hunter: an individual who has proven themself an elite member of humanity. Gon becomes determined to follow in his father''s footsteps, pass the rigorous Hunter Examination.', NULL, NULL, 27.7488, 8.386, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5616, 1042, 'tt0205410', NULL, 'Revolutionary Girl Utena', '少女革命ウテナ', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/riqymWBPqKmWpIvS3lVDYjZhwQ5.jpg', 'https://image.tmdb.org/t/p/original/802aSsZzIyOhbaL1bt19gp0RVYq.jpg', '"Never lose that strength or nobility, even when you grow up." When Utena was just a child and in the depths of sorrow, she found salvation in those words. They were the words of a prince, who bestowed upon her both a ring and the promise that it would lead her to him again. She never forgot the encounter. Now a teenager, Utena attends the prestigious Ohtori Academy; however, her strong sense of chivalry soon places her at odds with the student council and thrusts her into a series of mysterious and dangerous duels against its members.', NULL, NULL, 22.6728, 8.107, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5617, 16860, 'tt1047518', NULL, 'RahXephon: Pluralitas Concentio', 'ラーゼフォン 多元変奏曲', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/wK8yAt16bfQBaKBatAJxYRdpu9Y.jpg', 'https://image.tmdb.org/t/p/original/nlvmh1r91egemTd1QksOyptHcO7.jpg', 'Ayato and Haruka are middle-school sweethearts whose lives take a dire turn when the mysterious Mu invade Tokyo in the year 2012. Protecting humanity from the Mu may be Ayato''s destiny, but what he really wants is to regain the relationship he once had with Haruka... a love that will have to transcend space, time, and reality itself.', NULL, NULL, 0.9201, 5.8, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5618, 5895, 'tt0279077', NULL, 'FLCL', 'フリクリ', 'tv', 2000, 'https://image.tmdb.org/t/p/w500/FkgA8CcmiLJGVCRYRQ2g2UfVtF.jpg', 'https://image.tmdb.org/t/p/original/uiBb01nmHwyVTSILSMKJ4WIvijc.jpg', 'Naota is a normal boy who kills some time with a normal girl by a stream that flows underneath a bridge. Nothing unusual happens in this town. The fact that Haruhara Haruko crashes into the main character with her Vespa a short while later and subsequently hits him over the head with her Rickenbacker 4003 bass guitar doesn’t really make any difference to any other day here. The at first glance unconnected, bizarre events that don’t seem to follow any pattern whatsoever don’t change anything about Naota’s boring life, either – because nothing incredible ever happens in this town.', NULL, NULL, 11.2792, 7.9, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5619, 449574, 'tt5979874', NULL, 'Godzilla: Planet of the Monsters', 'GODZILLA 怪獣惑星', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/hAuZ7g6TqDLv5fOqXIPgYRguOkm.jpg', 'https://image.tmdb.org/t/p/original/5QAc8dsyOwJBGQ71mhOLMEivOsF.jpg', 'A desperate group of refugees attempts to recolonize Earth 20,000 years after Godzilla took over. But one young man wants revenge above all else.', NULL, NULL, 4.2115, 6.377, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5620, 34765, 'tt1132201', NULL, 'Bokurano', 'ぼくらの', 'tv', 2007, 'https://image.tmdb.org/t/p/w500/nxsG82r30eKyybItqVJjOCPbpwD.jpg', 'https://image.tmdb.org/t/p/original/iYfQrAAHCZcW3r4jxJz1hmP9Lx8.jpg', 'During a summer camp, 15 children, 8 males and 7 females, find a grotto by the sea. Deep within they discover working computers and some electronic equipment, and later the owner, a man called Kokopelli. Kokopelli claimed to be a programmer working on a brand new game, in which a large robot has to defend the Earth against fifteen alien invasions. He persuades the children to test the game and sign a contract. All but one of them signs; barely a moment later they mysteriously awaken on the shore believing what happened was just a dream.', NULL, NULL, 7.4758, 6.607, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5621, 406, 'tt0111873', NULL, 'Æon Flux', 'Æon Flux', 'tv', 1991, 'https://image.tmdb.org/t/p/w500/3745n05zXNMfWwkXMcCiF64838s.jpg', 'https://image.tmdb.org/t/p/original/3fPQATk8uzBlDbeqzvFXZk0ETNw.jpg', 'Æon Flux is set in a bizarre, dystopian future world. The title character is a tall, leather-clad secret agent from the nation of Monica, skilled in assassination and acrobatics. Her mission is to infiltrate the strongholds of the neighboring country of Bregna, which is led by her sometimes-nemesis and sometimes-lover Trevor Goodchild. Monica represents a dynamic anarchist society, while Bregna embodies a police state.', NULL, NULL, 5.6242, 7.6, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5622, 11662, 'tt0405821', NULL, 'Casshern', 'CASSHERN', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/naIjHWfQFge69GqeehgsekwDkbl.jpg', 'https://image.tmdb.org/t/p/original/nOovQqWWrGRkEkefR19syGO5a9i.jpg', 'Fifty years of war between the Great Eastern Federation and Europa - now merged as Eurasia - have taken their toll on planet Earth. As a result of the use of biological, chemical and nuclear weapons, much of Earth has become uninhabitable and people have become prey to new diseases. Professor Azuma''s "neo-cell" project, which is supposed to be the answer to mankind''s hardships, becomes a nightmare come true when mutants spawned from the experiment escape and declare war on the human race. Azuma''s son Tetsuya, who was killed during the previous war, is reborn into the cyborg Casshern as mankind''s last hope against the new mutant threat. This live-action sci-fi movie based on a 1973 Japanese animé of the same name.', NULL, NULL, 1.8794, 5.895, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5623, 58244, 'tt1374992', NULL, 'Upside Down', 'Upside Down', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/wImo0dC72HRoI5QO85dGavmxW6q.jpg', 'https://image.tmdb.org/t/p/original/sKWh9hF0ekVhHHyGuJwdA3fnMGZ.jpg', 'In an alternate universe where twinned worlds have opposite gravities, a young man battles interplanetary prejudice and the laws of physics in his quest to reunite with the long-lost girl of his dreams in this visually stunning romantic adventure that poses the question: what if love was stronger than gravity?', NULL, NULL, 2.9779, 6.278, 0, 1.01, '2026-07-29 20:51:09', '2026-07-29 20:51:09');
UPDATE "recommendations" SET "tmdb_id"=6114, "imdb_id"='tt0103874', "igdb_id"=NULL, "title"='Bram Stoker''s Dracula', "original_title"='Bram Stoker''s Dracula', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/4ZbUxjY5DZ7RCxGwvzSEr4rThd1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/88S6EYQBVyQktDfSqsB33I169jN.jpg', "overview"='Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.6015, "vote_average"=7.451, "is_ambiguous"=0, "evidence_score"=22.694, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=1;
