UPDATE "recommendations" SET "tmdb_id"=10957, "imdb_id"='tt0088814', "igdb_id"=NULL, "title"='The Black Cauldron', "original_title"='The Black Cauldron', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/h64i9e6oJs2jrDZ4QzspXMqZhPF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4idEU92m0oR1BWa1iwb5pZ9bWCu.jpg', "overview"='Taran is an assistant pigkeeper with boyish dreams of becoming a great warrior. However, he has to put the daydreaming aside when his charge, an oracular pig named Hen Wen, is kidnapped by an evil lord known as the Horned King. The villain hopes Hen will show him the way to The Black Cauldron, which has the power to create a giant army of unstoppable soldiers.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2452, "vote_average"=6.441, "is_ambiguous"=0, "evidence_score"=8.974, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=22;
