UPDATE "recommendations" SET "tmdb_id"=8967, "imdb_id"='tt0478304', "igdb_id"=NULL, "title"='The Tree of Life', "original_title"='The Tree of Life', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/l8cwuB5WJSoj4uMAsnzuHBOMaSJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xq1HIwZq9VbuvMQELAua1nqEkH.jpg', "overview"='The impressionistic story of a Texas family in the 1950s. The film follows the life journey of the eldest son, Jack, through the innocence of childhood to his disillusioned adult years as he tries to reconcile a complicated relationship with his father. Jack finds himself a lost soul in the modern world, seeking answers to the origins and meaning of life while questioning the existence of faith.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.1362, "vote_average"=6.719, "is_ambiguous"=0, "evidence_score"=1.99746153846153866e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=34;
UPDATE "recommendations" SET "tmdb_id"=75612, "imdb_id"='tt1483013', "igdb_id"=NULL, "title"='Oblivion', "original_title"='Oblivion', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2kVt8oj1cSz4GAP0Hi8SESOiH0T.jpg', "overview"='Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.7316, "vote_average"=6.686, "is_ambiguous"=0, "evidence_score"=8.87833333333333207e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=35;
UPDATE "recommendations" SET "tmdb_id"=7131, "imdb_id"='tt0338526', "igdb_id"=NULL, "title"='Van Helsing', "original_title"='Van Helsing', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/gsFun8nATm52aGHeT8ueAel98nE.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/d72ROyJqXQtw2OupW0l15eicRAF.jpg', "overview"='Famed monster slayer Gabriel Van Helsing is dispatched to Transylvania to assist the last of the Valerious bloodline in defeating Count Dracula. Anna Valerious reveals that Dracula has formed an unholy alliance with Dr. Frankenstein''s monster and is hell-bent on exacting a centuries-old curse on her family.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.9164, "vote_average"=6.425, "is_ambiguous"=0, "evidence_score"=17.568, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=38;
UPDATE "recommendations" SET "tmdb_id"=274854, "imdb_id"='tt1618442', "igdb_id"=NULL, "title"='The Last Witch Hunter', "original_title"='The Last Witch Hunter', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mXmvN6drkdU1PWFF92AGklEVIa3.jpg', "overview"='The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6492, "vote_average"=6.017, "is_ambiguous"=0, "evidence_score"=2.9695652173913043e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=39;
