UPDATE "recommendations" SET "tmdb_id"=1923, "imdb_id"='tt0105665', "igdb_id"=NULL, "title"='Twin Peaks: Fire Walk with Me', "original_title"='Twin Peaks: Fire Walk with Me', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/mxsGXqetGnirf99qapYd5MMY1VL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/amGU1FpELmenVvNmPShW58Orepy.jpg', "overview"='In the questionable town of Deer Meadow, Washington, FBI Agent Desmond inexplicably disappears while hunting for the man who murdered a teen girl. The killer is never apprehended, and, after experiencing dark visions and supernatural encounters, Agent Dale Cooper chillingly predicts that the culprit will claim another life. Meanwhile, in the more cozy town of Twin Peaks, hedonistic beauty Laura Palmer hangs with lowlifes and seems destined for a grisly fate.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.5699, "vote_average"=7.4, "is_ambiguous"=0, "evidence_score"=1.83816666666666677e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=121;
UPDATE "recommendations" SET "tmdb_id"=2039, "imdb_id"='tt0093565', "igdb_id"=NULL, "title"='Moonstruck', "original_title"='Moonstruck', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/2mnVWpvsHEHHnfvLn1NXYVvBGl5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5RQ5SIcrtKeUYeYeJLRTljR8LcN.jpg', "overview"='37-year-old Italian-American widow Loretta Castorini believes she is unlucky in love, and so accepts a marriage proposal from her boyfriend Johnny, even though she doesn''t love him. When she meets his estranged younger brother Ronny, an emotional and passionate man, she finds herself drawn to him. She tries to resist, but Ronny, who blames his brother for the loss of his hand, has no scruples about aggressively pursuing her while Johnny is out of the country. As Loretta falls for Ronny, she learns that she''s not the only one in her family with a secret romance.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.0658, "vote_average"=6.843, "is_ambiguous"=0, "evidence_score"=9.014, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=124;
