UPDATE "recommendations" SET "tmdb_id"=83542, "imdb_id"='tt1371111', "igdb_id"=NULL, "title"='Cloud Atlas', "original_title"='Cloud Atlas', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cHm1lWAok12vwnTHqzprbPTk49q.jpg', "overview"='A set of six nested stories spanning time between the 19th century and a distant post-apocalyptic future. Cloud Atlas explores how the actions and consequences of individual lives impact one another throughout the past, the present and the future. Action, mystery and romance weave through the story as one soul is shaped from a killer into a hero and a single act of kindness ripples across centuries to inspire a revolution in the distant future.  Based on the award winning novel by David Mitchell. Directed by Tom Tykwer and the Wachowskis.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.4316, "vote_average"=6.896, "is_ambiguous"=0, "evidence_score"=14.0075, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=432;
