UPDATE "recommendations" SET "tmdb_id"=9387, "imdb_id"='tt0082198', "igdb_id"=NULL, "title"='Conan the Barbarian', "original_title"='Conan the Barbarian', "media_type"='movie', "release_year"=1982, "poster_url"='https://image.tmdb.org/t/p/w500/qw2A587Ee61IwcSOLNFRhuOACZZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fNp2ikvY8WZTyVbK1iXW84RLbO5.jpg', "overview"='A horde of rampaging warriors massacre the parents of young Conan and enslave the young child for years on The Wheel of Pain. As the sole survivor of the childhood massacre, Conan is released from slavery and taught the ancient arts of fighting. Transforming himself into a killing machine, Conan travels into the wilderness to seek vengeance on Thulsa Doom, the man responsible for killing his family. In the wilderness, Conan takes up with the thieves Valeria and Subotai. The group comes upon King Osric, who wants the trio of warriors to help rescue his daughter who has joined Doom in the hills.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.2516, "vote_average"=6.804, "is_ambiguous"=0, "evidence_score"=9.018, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=1396;
