UPDATE "recommendations" SET "tmdb_id"=62177, "imdb_id"='tt1217209', "igdb_id"=NULL, "title"='Brave', "original_title"='Brave', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qx9ts2hBYJrkIQxhryitxnLlm2u.jpg', "overview"='In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest — and serving as comic relief — are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.4096, "vote_average"=7.033, "is_ambiguous"=0, "evidence_score"=7.034, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=1862;
