UPDATE "recommendations" SET "tmdb_id"=3040, "imdb_id"='tt0403358', "igdb_id"=NULL, "title"='Night Watch', "original_title"='Ночной дозор', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/mWdfItjr9tZtsSgjkqB8YhORF8T.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2f6La6ZJDIQTNPcn2WSR6qdXy8Q.jpg', "overview"='Among normal humans live the "Others" possessing various supernatural powers. They are divided up into the forces of light and the forces of the dark, who signed a truce several centuries ago to end a devastating battle. Ever since, the forces of light govern the day while the night belongs to their dark opponents. In modern day Moscow the dark Others actually roam the night as vampires while a "Night Watch" of light forces, among them Anton, the movie''s protagonist, try to control them and limit their outrage', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1513, "vote_average"=6.2, "is_ambiguous"=0, "evidence_score"=1.98209090909090903e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=2202;
