UPDATE "recommendations" SET "tmdb_id"=748853, "imdb_id"='tt13429362', "igdb_id"=NULL, "title"='In the Earth', "original_title"='In the Earth', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/a2e9GLb14xX1DFv80nsioci5Zld.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fjRlDPqo2qqMBoUItMtTDZe9kvZ.jpg', "overview"='As a deadly virus ravages the world, Dr. Martin Lowery embarks on a mission to reach test site ATU327A, a research hub deep in the Arboreal Forest. The arduous journey, guided by park scout Alma, is set back by a nighttime attack that leaves the two bruised and shoeless. When they run into Zach, a man living off the grid, they gratefully accept his help. Zach’s intentions aren’t exactly what they seem, however, and a path out of the forest and into safety quickly fades as the line between myth and science blurs.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2304, "vote_average"=5.596, "is_ambiguous"=0, "evidence_score"=6.51500000000000056e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-29 20:51:09' WHERE "id"=2577;
