UPDATE "recommendations" SET "tmdb_id"=19255, "imdb_id"='tt1176740', "igdb_id"=NULL, "title"='Away We Go', "original_title"='Away We Go', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/zWxjopWXpnC1vSbnO7mw2URna22.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rSEZ4e8rWCk9SsRvuwyxtLLUV0w.jpg', "overview"='Verona and Burt have moved to Colorado to be close to Burt''s parents but, with Verona expecting their first child, Burt''s parents inexplicably decide to move to Belgium, now leaving them in a place they hate and without a support structure in place. They set off on a whirlwind tour of of disparate locations where they have friends or relatives, sampling not only different cities and climates but also different families. Along the way they realize that the journey is less about discovering where they want to live and more about figuring out what type of parents they want to be.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4499, "vote_average"=6.665, "is_ambiguous"=0, "evidence_score"=6.04, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-29 20:51:09' WHERE "id"=2874;
