UPDATE "recommendations" SET "tmdb_id"=111, "imdb_id"='tt0086250', "igdb_id"=NULL, "title"='Scarface', "original_title"='Scarface', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1qM2BYNE11Viby8ImC9LC00DgDr.jpg', "overview"='After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', "external_url"=NULL, "platforms"=NULL, "popularity"=20.7473, "vote_average"=8.155, "is_ambiguous"=0, "evidence_score"=3.08666666666666644e+00, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-07-29 20:51:09' WHERE "id"=4553;
UPDATE "recommendations" SET "tmdb_id"=4616, "imdb_id"='tt0112230', "igdb_id"=NULL, "title"='Xena: Warrior Princess', "original_title"='Xena: Warrior Princess', "media_type"='tv', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/qjUn6GVZVDifLHB7bvVrgZsOfzE.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1V7WuDv5kmzwCCNd9CNQvOmqHdm.jpg', "overview"='Xena is an infamous warrior on a quest to seek redemption for her past sins against the innocent. Accompanied by her comrade-in-arms Gabrielle, the campy couple use their formidable fighting skills to help those who are unable to defend themselves.', "external_url"=NULL, "platforms"=NULL, "popularity"=51.8502, "vote_average"=7.564, "is_ambiguous"=0, "evidence_score"=3.00333333333333341e+00, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-07-29 20:51:09' WHERE "id"=4574;
UPDATE "recommendations" SET "tmdb_id"=38543, "imdb_id"='tt1233301', "igdb_id"=NULL, "title"='Ironclad', "original_title"='Ironclad', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/h7CP12wAThhw2WSOA1uIAqxg1fS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rprg34i9MfIRAJdBcjAWaV7JXRe.jpg', "overview"='In the year 1215, the rebel barons of England have forced their despised King John to put his royal seal on the Magna Carta, a seminal document that upheld the rights of free men. Yet within months of pledging himself to the great charter, the King reneged on his word and assembled a mercenary army on the south coast of England with the intention of bringing the barons and the country back under his tyrannical rule. Barring his way stood the mighty Rochester castle, a place that would become the symbol of the rebel''s momentous struggle for justice and freedom.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7969, "vote_average"=6.151, "is_ambiguous"=0, "evidence_score"=2.005, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-07-29 20:51:09' WHERE "id"=4579;
